def word_break(s: str, words: list[str]) -> bool:
    """
    Returns True if s can be split into a sequence of one or more words from words.
    Each word may be reused. Returns True for an empty s.
    """
    def dfs(i: int) -> bool:
        # If we've reached the end of the string, return True
        if i == len(s):
            return True

        # Try each word in the list
        for word in words:
            # If the string starts with the word, recursively try the rest of the string
            if s.startswith(word, i):
                if dfs(i + len(word)):
                    return True

        # If we've tried all words and haven't returned True, return False
        return False

    # Start the DFS at the beginning of the string
    return dfs(0)
