def regex_match(s: str, p: str) -> bool:
    """
    Returns True if pattern p matches the whole of s.
    In p, '.' matches any single character and '*' matches zero or more of the preceding element.
    Every '*' is preceded by a valid character or '.'.
    """
    def match(i, j):
        # If we've reached the end of both strings, they match
        if i == len(s) and j == len(p):
            return True

        # If we've reached the end of the string but not the pattern, they don't match
        if i == len(s) or j == len(p):
            return False

        # If the current character in the pattern is '.', it matches any character in the string
        if p[j] == '.':
            return match(i + 1, j + 1)

        # If the current character in the pattern is '*', it matches zero or more of the preceding element
        if p[j] == '*':
            # If the preceding element is '.', it matches any character
            if j == 0 or p[j - 1] == '.':
                return match(i, j + 1) or match(i + 1, j + 1)
            # If the preceding element is a character, it matches zero or more of that character
            else:
                return match(i, j + 2) and (i <= len(s) - 1 and s[i] == p[j - 1] or match(i + 1, j + 2))

        # If the current character in the pattern is not '*' or '.', it must match the current character in the string
        return match(i + 1, j + 1) and (i <= len(s) - 1 and s[i] == p[j])

    return match(0, 0)
```

