def group_anagrams(words: List[str]) -> List[List[str]]:
    anagrams = {}
    for word in words:
        sorted_word = ''.join(sorted(word))
        if sorted_word in anagrams:
            anagrams[sorted_word].append(word)
        else:
            anagrams[sorted_word] = [word]

    # Sort the words within each group alphabetically
    for group in anagrams.values():
        group.sort()

    # Sort the groups by their first word
    sorted_anagrams = sorted(anagrams.items(), key=lambda x: x[1][0])

    # Return the sorted groups
    return [group[1] for group in sorted_anagrams]

