def paths_with_obstacles(grid: list[list[int]]) -> int:
    if grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = 1
    for i in range(1, m):
        if grid[i][0] != 1:
            dp[i][0] = dp[i-1][0]
    for j in range(1, n):
        if grid[0][j] != 1:
            dp[0][j] = dp[0][j-1]

    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] != 1:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[-1][-1]
