def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, 
    the binary operators + - * /, parentheses, and spaces.

    * and / bind tighter than + and -, and operators of equal precedence 
    associate left to right. Integer division truncates toward zero.

    :param expr: The arithmetic expression to be evaluated.
    :return: The result of the evaluated expression.
    """
    def tokenize():
        # Split the expression into tokens (operators and operands)
        tokens = []
        token = ""
        for char in expr:
            if char.isspace():
                if token:
                    tokens.append(token)
                    token = ""
            elif char in "+-*/()":
                if token:
                    tokens.append(token)
                    token = ""
                tokens.append(char)
            else:
                token += char
        if token:
            tokens.append(token)
        return tokens

    def apply_operator(tokens, i):
        # Apply the operator at index i to the two operands before it
        op = tokens[i]
        op1 = tokens[i-1]
        op2 = tokens[i-2]
        if op == "+":
            return op1 + op2
        elif op == "-":
            return op1 - op2
        elif op == "*":
            return op1 * op2
        elif op == "/":
            return op1 // op2  # Integer division truncates toward zero

    def apply_parentheses(tokens):
        # Apply parentheses by evaluating the expression inside them
        stack = []
        for i, token in enumerate(tokens):
            if token == "(":
                # Push the opening parenthesis onto the stack
                stack.append(i)
            elif token == ")":
                # Pop the opening parenthesis from the stack
                opening_idx = stack.pop()
                # Apply operators inside the parentheses
                while tokens[i-1] != ")":
                    i -= 1
                    if tokens[i] == ")":
                        break
                    tokens[i] = apply_operator(tokens, i)
                # Replace the parentheses with the result
                tokens[opening_idx] = tokens[i]
                tokens.pop(i)
                tokens.pop(opening_idx)
        return tokens

    def parse(tokens):
        # Parse the tokens into a binary expression tree
        stack = []
        for token in tokens:
            if token in "+-*/":
                # Pop the two operands from the stack
                op2 = stack.pop()
                op1 = stack.pop()
                # Push the operator onto the stack with the operands as children
                stack.append((token, op1, op2))
            else:
                # Push the operand onto the stack
                stack.append(int(token))
        return stack

    def apply_expression_tree(tree):
        # Apply the binary expression tree by recursively evaluating the left and right subtrees
        if isinstance(tree, tuple):
            op, left, right = tree
            return apply_operator([op, left, right], 0)
        else:
            return tree

    tokens = tokenize()
    tokens = apply_parentheses(tokens)
    tree = parse(tokens)
    return apply_expression_tree(tree)

