def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, 
    the binary operators + - * /, parentheses, and spaces.

    * and / bind tighter than + and -, and operators of equal precedence 
    associate left to right. Integer division truncates toward zero.

    Parameters:
    expr (str): The arithmetic expression to evaluate.

    Returns:
    int: The result of the evaluated expression.
    """

    # Define operator precedence
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    # Split the expression into numbers and operators
    tokens = []
    num = ''
    for char in expr:
        if char.isdigit():
            num += char
        else:
            if num:
                tokens.append(int(num))
                num = ''
            tokens.append(char)
    if num:
        tokens.append(int(num))

    # Infix to postfix conversion
    postfix = []
    stack = []
    for token in tokens:
        if token in precedence:
            while stack and stack[-1] in precedence and precedence[stack[-1]] >= precedence[token]:
                postfix.append(stack.pop())
            stack.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                postfix.append(stack.pop())
            stack.pop()
        else:
            postfix.append(token)
    while stack:
        postfix.append(stack.pop())

    # Evaluate postfix expression
    stack = []
    for token in postfix:
        if isinstance(token, int):
            stack.append(token)
        else:
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                stack.append(left + right)
            elif token == '-':
                stack.append(left - right)
            elif token == '*':
                stack.append(left * right)
            elif token == '/':
                stack.append(left // right)
    return stack[0]

